export const LANGUAGES = ["fa", "prs", "ps", "en", "ar", "fr", "de", "tr", "es"] as const;
export type Language = (typeof LANGUAGES)[number];

export const LANGUAGE_LABELS: Record<Language, string> = {
  fa: "فارسی",
  prs: "دری",
  ps: "پشتو",
  en: "English",
  ar: "العربية",
  fr: "Français",
  de: "Deutsch",
  tr: "Türkçe",
  es: "Español",
};

export const LANGUAGE_DIRECTION: Record<Language, "rtl" | "ltr"> = {
  fa: "rtl",
  prs: "rtl",
  ps: "rtl",
  en: "ltr",
  ar: "rtl",
  fr: "ltr",
  de: "ltr",
  tr: "ltr",
  es: "ltr",
};

// نگاشت زبان مرورگر (navigator.language, مثلا "de-CH" یا "fr-FR") به یکی
// از زبان‌های پشتیبانی‌شده بالا — برای تشخیص خودکار زبان کاربر هنگام
// اولین ورود (پیش از اینکه خودش چیزی انتخاب کرده باشد).
// همان الگوی حذف پیشوند زبان که middleware.ts استفاده می‌کند، اینجا هم
// هست تا هم middleware (سرور) و هم LanguageProvider (کلاینت) از یک
// منبع واحد استفاده کنند و از هم جدا نیفتند.
// پیش‌فرض سایت دری (افغانستان) است، پس prs بدون پیشوند می‌ماند و بقیه
// زبان‌ها (از جمله fa/فارسی ایران) پیشوند می‌گیرند.
export const LOCALE_URL_PREFIXES = LANGUAGES.filter((l) => l !== "prs");

export function stripLocaleFromPath(pathname: string): { locale: Language | null; rest: string } {
  for (const locale of LOCALE_URL_PREFIXES) {
    if (pathname === `/${locale}` || pathname.startsWith(`/${locale}/`)) {
      const rest = pathname.slice(`/${locale}`.length);
      return { locale, rest: rest === "" ? "/" : rest };
    }
  }
  return { locale: null, rest: pathname };
}

// وقتی کاربر از سوییچر زبان عوض می‌کند، آدرس هم باید همراهش عوض شود
// (مثلا از /products/5 به /fr/products/5)، وگرنه URL و زبان نمایش‌
// داده‌شده هماهنگ نمی‌مانند و hreflang/بوکمارک بی‌معنا می‌شود.
// دری (prs) عمدا بدون پیشوند است.
export function getLocalizedPath(currentPathname: string, targetLanguage: Language): string {
  const { rest } = stripLocaleFromPath(currentPathname);

  if (targetLanguage === "prs") return rest;

  return rest === "/" ? `/${targetLanguage}` : `/${targetLanguage}${rest}`;
}

export function detectLanguageFromBrowser(browserLocale: string): Language | null {
  const code = browserLocale.toLowerCase().split("-")[0];

  const map: Record<string, Language> = {
    fa: "fa",
    prs: "prs",
    ps: "ps",
    pbu: "ps",
    en: "en",
    ar: "ar",
    fr: "fr",
    de: "de",
    tr: "tr",
    es: "es",
    // آلمانی سوئیس (de-CH) هم به همین "de" نگاشت می‌شود؛ سوئیس زبان
    // مستقل ندارد، بلکه از آلمانی/فرانسوی/ایتالیایی استفاده می‌کند.
  };

  // قبلا این تابع وقتی زبان مرورگر ناشناخته بود، به‌صورت خاموش "prs"
  // برمی‌گرداند — یعنی فراخوان نمی‌توانست تشخیص بدهد که آیا واقعا زبان
  // مرورگر دری تشخیص داده شده یا صرفا یک پیش‌فرض بی‌معنا برگشته. حالا
  // در نبود تطبیق واقعی null برمی‌گرداند تا فراخوان (LanguageProvider)
  // بتواند در آن حالت به مرحله بعدی (تشخیص جغرافیایی) برود، نه اینکه
  // کورکورانه دری را جایگزین سیگنال واقعی‌تر جغرافیا کند.
  return map[code] || null;
}

// نکته درباره «دری» (prs): دری و فارسی همان یک زبان با تفاوت‌های
// لهجه‌ای/واژگانی جزئی هستند (نه دو زبان جدا با دستور زبان متفاوت مثل
// پشتو)؛ نسخه قبلی این فایل به‌اشتباه واژه‌های پشتو را به‌جای دری
// گذاشته بود (مثلا "کور" برای خانه که پشتو است، نه دری که می‌شود
// "خانه"). این نسخه آن اشتباه را اصلاح کرده: dari با فارسی یکسان
// نوشته می‌شود مگر در چند مورد که واژه رایج افغانستانی متفاوت است.
//
// درباره پشتو (ps) و عربی (ar): ترجمه‌ها تا حد امکان درست انجام شده،
// اما پیشنهاد می‌شود پیش از انتشار نهایی توسط یک گویشور بومی بازبینی
// شوند — من (Claude) در این دو زبان به‌اندازه فارسی/انگلیسی/فرانسوی/
// آلمانی مطمئن نیستم.

// نکته مهم: قبلا تایپ اینجا `Record<Language, string>` بود که یعنی هر
// کلید مجبور بود مقدار هر ۹ زبان را داشته باشد — یعنی همین که ترکی
